import{_ as a,o as t,c as r,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"Ceph Crimson/SeaStore 2021-05-12","description":"","frontmatter":{"title":"Ceph Crimson/SeaStore 2021-05-12","date":"2021-05-12T00:00:00.000Z","updated":"2021-05-13T00:00:00.000Z","tags":["Ceph","代码审查","性能优化","错误调试","系统指标"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Crimson_SeaStore_2021-05-12.md","filePath":"posts/2021/Ceph_Crimson_SeaStore_2021-05-12.md","lastUpdated":1780459816000}'),n={name:"posts/2021/Ceph_Crimson_SeaStore_2021-05-12.md"};function s(i,e,l,h,d,_){return t(),r("div",null,[...e[0]||(e[0]=[o('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="关键细节" tabindex="-1">关键细节 <a class="header-anchor" href="#关键细节" aria-label="Permalink to &quot;关键细节&quot;">​</a></h4><ul><li><strong>代码审查与性能分析</strong>：会议讨论了上周的代码审查，重点关注电阻指标和性能计数器的差异，并探讨了系统指标在标签支持方面的优势。</li><li><strong>PR讨论</strong>：讨论了与Srihan合作的PR#39772，并分享了相关链接。</li><li><strong>段错误调试</strong>：报告了单元测试中发现的段错误，该错误出现在主分支中，目前仍在调试中。</li><li><strong>环境差异</strong>：讨论了环境差异可能导致的问题，特别是非确定性调度可能引发的bug。</li><li><strong>Ceph存储系统改进</strong>：详细讨论了ONode Manager处理冲突的方式，计划通过引入新的机制来解决问题。</li><li><strong>性能计数器与系统指标</strong>：讨论了性能计数器与系统指标的优劣，决定继续使用性能计数器，并可能在未来集成系统指标。</li></ul><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li><strong>继续使用性能计数器</strong>：尽管系统指标提供了更多的灵活性和标签支持，但决定继续使用性能计数器作为当前的解决方案。</li><li><strong>集成系统指标</strong>：计划在未来集成系统指标，特别是在性能优化和问题追踪方面。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li><strong>解决段错误</strong>：继续调试并解决在单元测试中发现的段错误。</li><li><strong>改进ONode Manager</strong>：实施新的机制来改进ONode Manager的处理冲突方式。</li><li><strong>集成系统指标</strong>：开始规划和实施系统指标的集成工作，以提供更详细的性能数据和标签支持。</li></ul><h4 id="其他讨论" tabindex="-1">其他讨论 <a class="header-anchor" href="#其他讨论" aria-label="Permalink to &quot;其他讨论&quot;">​</a></h4><ul><li><strong>会议结束</strong>：会议在讨论了所有议题后顺利结束，没有其他待处理事项。</li></ul><p>本次会议主要聚焦于Ceph存储系统的性能优化和问题解决，特别是在事务管理和性能计数器方面的讨论为未来的开发和优化工作奠定了基础。</p>',10)])])}const u=a(n,[["render",s]]);export{p as __pageData,u as default};
